import React from 'react';
import styled from 'styled-components';

const CardsContainer = styled.div`
  display: flex;
  justify-content: space-around; /* Distribute space around the cards */
  flex-wrap: wrap; /* Allow wrapping on smaller screens */
  margin: 20px 0; /* Add some margin around the container */
`;

const CardWrapper = styled.div`
  position: relative;
  width: 500px; /* Width of each card */
  height: 254px;
  transition: 200ms;
  margin: 10px; /* Add space between cards */
  overflow: hidden; /* Prevent overflow during hover effects */

  &:active {
    height: 245px; /* Slightly change height on active state */
  }

  &:hover #card {
    filter: brightness(1.1); /* Brighten card on hover */
  }
`;

const StyledCard = styled.div`
  position: absolute;
  inset: 0;
  z-index: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 20px;
  transition: 700ms;
  background: #302f2f;

  #prompt {
    bottom: 8px;
    left: 12px;
    z-index: 20;
    font-size: 50px;
    font-weight: bold;
    transition: 300ms ease-in-out-out;
    max-width: 1000px;
    color: rgb(255, 255, 255);
  }

  .title {
    opacity: 0;
    transition: opacity 300ms ease-in-out, transform 300ms ease-in-out;
    position: absolute;
    font-size: 20px;
    margin-right: 10px;
    margin-left: 10px;
    text-align: center;
    color: black;
    transform: translateY(20px); /* Slightly translate up for smooth appearance */
  }

  .tracker:hover ~ #card .title {
    opacity: 1;
    transform: translateY(0); /* Bring into view */
  }

  .tracker {
    position: absolute;
    z-index: 200;
    width: 100%;
    height: 100%;
  }

  .tracker:hover {
    cursor: pointer;
  }

  .tracker:hover ~ #card #prompt {
    opacity: 0;
  }
`;

const Card = () => {
  return (
    <CardsContainer>
      {[...Array(3)].map((_, index) => (
        <CardWrapper key={index}>
          <StyledCard id="card">
            <p id="prompt">nexAR {index + 1}</p>
            <div className="title">
              We understand the importance of a strong brand identity, that's why our
              team is dedicated to helping you create and maintain a cohesive identity
              that appeals to your target audience and helps you stand out from the
              competition.
            </div>
          </StyledCard>
          {Array.from({ length: 25 }, (_, i) => (
            <div className={`tracker tr-${i + 1}`} key={i} />
          ))}
        </CardWrapper>
      ))}
    </CardsContainer>
  );
};

export default Card;
